		p[i] -= 1
	base = int(n ** 0.5 + 1)
	a = [-1] * n
	r = [-1] * n
	for i in range(n):
		r[p[i]] = i
		i2 = i
		for _ in range(base):
			i = p[i]
		a[i2] = i
