			x -= 1
			y -= 1
			temp = p[x]
			p[x] = p[y]
			p[y] = temp
			r[p[x]] = x
			r[p[y]] = y
			for z in (x, y):
				for __ in range(base + 1):
					z = r[z]
				j = i = z
